import { readFileSync } from 'node:fs';
import { FEATURES, SQUARE_ROOT, type Scaling } from './features.ts';
export interface Condition {
  feature: number;
  comparison: string;
  threshold: number;
}
export interface Rule {
  name: string;
  conditions: Condition[];
}
export function readRules(): Rule[] {
  return readFileSync('input/segment_rules.txt', 'ascii')
    .split('\n')
    .slice(0, -1)
    .map((line) => {
      const [name, ...words] = line.split(' ');
      const conditions: Condition[] = [];
      for (let index = 0; index < words.length; index += 3) {
        conditions.push({
          feature: FEATURES.indexOf(words[index]),
          comparison: words[index + 1],
          threshold: Number(words[index + 2]),
        });
      }
      return { name, conditions };
    });
}
export function matchingRule(center: number[], rules: Rule[]): number {
  return rules.findIndex((rule) =>
    rule.conditions.every((condition) =>
      condition.comparison === '>'
        ? center[condition.feature] > condition.threshold
        : center[condition.feature] < condition.threshold,
    ),
  );
}
export function originalCenter(center: number[], scaling: Scaling[]): number[] {
  return center.map((coordinate, feature) => {
    const value = scaling[feature].mean + scaling[feature].sd * coordinate;
    return SQUARE_ROOT.has(feature) ? value * value : value;
  });
}

import { mkdirSync, writeFileSync } from 'node:fs';
export function real(value: number | null): string {
  if (value === null) return '-';
  let text = Math.abs(value).toFixed(4);
  if (text.includes('e')) text = BigInt(Math.abs(value)).toString() + '.0000';
  return value < 0 && /[1-9]/.test(text) ? '-' + text : text;
}
export const rounded = (value: number) => Number(real(value));
export function amount(value: number): string {
  const magnitude = Math.abs(value);
  return (
    (value < 0 ? '-' : '') +
    Math.floor(magnitude / 100) +
    '.' +
    String(magnitude % 100).padStart(2, '0')
  );
}
export function writeReport(name: string, lines: string[]) {
  mkdirSync('output', { recursive: true });
  writeFileSync(`output/${name}`, lines.length ? lines.join('\n') + '\n' : '', 'ascii');
}

import { readFileSync } from 'node:fs';

export type Method = 'forgy' | 'maximin' | 'kmeanspp';
export interface Settings {
  reference: number;
  snapshot: number;
  outcomeDays: number;
  minK: number;
  maxK: number;
  methods: Method[];
  restarts: number;
  iterations: number;
  seed: number;
  subsamples: number;
  percent: number;
  outlierSD: number;
  overdueFactor: number;
  orderBins: number[];
  topCategories: number;
  topCustomers: number;
  periodDays: number;
  periods: number;
}
export interface Transaction {
  customer: string;
  day: number;
  order: string;
  category: string;
  amount: number;
}
export interface Order {
  id: string;
  customer: string;
  day: number;
  net: number;
  rows: Transaction[];
}
export interface TransactionData {
  settings: Settings;
  rows: Transaction[];
  customers: Set<string>;
  count: number;
  duplicates: number;
  zero: number;
}
const readLines = (name: string) => readFileSync(`input/${name}`, 'ascii').split('\n').slice(0, -1);

export function readTransactions(): TransactionData {
  const parameters = new Map(
    readLines('params.txt').map((line) => {
      const [key, ...values] = line.split(' ');
      return [key, values];
    }),
  );
  const values = (key: string) => parameters.get(key)!;
  const number = (key: string) => Number(values(key)[0]);
  const methods = values('METHODS').map((value) => {
    if (value === 'forgy' || value === 'maximin' || value === 'kmeanspp') return value;
    throw new Error('Unknown initialization method');
  });
  const settings: Settings = {
    reference: number('REFERENCE_DAY'),
    snapshot: number('SNAPSHOT_DAY'),
    outcomeDays: number('OUTCOME_DAYS'),
    minK: Number(values('K_RANGE')[0]),
    maxK: Number(values('K_RANGE')[1]),
    methods,
    restarts: number('RESTARTS'),
    iterations: number('MAX_ITERATIONS'),
    seed: number('SEED'),
    subsamples: number('SUBSAMPLES'),
    percent: number('SUBSAMPLE_PERCENT'),
    outlierSD: number('OUTLIER_SD'),
    overdueFactor: number('OVERDUE_FACTOR'),
    orderBins: values('ORDER_BINS').map(Number),
    topCategories: number('TOP_CATEGORIES'),
    topCustomers: number('TOP_CUSTOMERS'),
    periodDays: number('PERIOD_DAYS'),
    periods: number('PERIODS'),
  };
  const records = readLines('transactions.csv').slice(1);
  const seen = new Set<string>();
  const customers = new Set<string>();
  const rows: Transaction[] = [];
  let duplicates = 0;
  let zero = 0;
  for (const text of records) {
    const [customer, day, order, category, amount] = text.split(',');
    customers.add(customer);
    if (seen.has(text)) {
      duplicates++;
      continue;
    }
    seen.add(text);
    if (Number(amount) === 0) {
      zero++;
      continue;
    }
    rows.push({ customer, day: Number(day), order, category, amount: Number(amount) });
  }
  return { settings, rows, customers, count: records.length, duplicates, zero };
}

export function groupOrders(rows: Transaction[], first: number, last: number): Order[] {
  const orders = new Map<string, Order>();
  for (const row of rows) {
    if (row.day < first || row.day > last) continue;
    let order = orders.get(row.order);
    if (!order) {
      order = { id: row.order, customer: row.customer, day: row.day, net: 0, rows: [] };
      orders.set(row.order, order);
    }
    order.day = Math.min(order.day, row.day);
    order.net += row.amount;
    order.rows.push(row);
  }
  return [...orders.values()];
}

import { squaredDistance, meanPoint } from './kmeans.ts';
export interface Partition {
  segments: { members: number[]; center: number[] }[];
  assignment: number[];
  sse: number;
}
export interface Indices {
  silhouettes: number[];
  silhouette: number;
  calinski_harabasz: number;
  davies_bouldin: number;
}
export function distanceTable(points: number[][]): number[][] {
  const table: number[][] = points.map(() => Array(points.length).fill(0));
  for (let first = 0; first < points.length; first++) {
    for (let second = first + 1; second < points.length; second++) {
      table[first][second] = Math.sqrt(squaredDistance(points[first], points[second]));
      table[second][first] = table[first][second];
    }
  }
  return table;
}
export function clusterIndices(
  points: number[][],
  solution: Partition,
  distances: number[][],
): Indices {
  const { segments, assignment, sse } = solution;
  const silhouettes: number[] = [];
  for (let index = 0; index < points.length; index++) {
    const own = segments[assignment[index]];
    if (own.members.length === 1) {
      silhouettes.push(0);
      continue;
    }
    let within = 0;
    let other = Infinity;
    for (const member of own.members) if (member !== index) within += distances[index][member];
    within /= own.members.length - 1;
    for (let segment = 0; segment < segments.length; segment++) {
      if (segment === assignment[index]) continue;
      let total = 0;
      for (const member of segments[segment].members) total += distances[index][member];
      other = Math.min(other, total / segments[segment].members.length);
    }
    const denominator = Math.max(within, other);
    silhouettes.push(denominator === 0 ? 0 : (other - within) / denominator);
  }
  const global = meanPoint(points);
  const scatters: number[] = [];
  let between = 0;
  let totalSilhouette = 0;
  for (const value of silhouettes) totalSilhouette += value;
  for (const segment of segments) {
    between += segment.members.length * squaredDistance(segment.center, global);
    let total = 0;
    for (const member of segment.members) {
      total += Math.sqrt(squaredDistance(points[member], segment.center));
    }
    scatters.push(total / segment.members.length);
  }
  let totalDB = 0;
  for (let first = 0; first < segments.length; first++) {
    let maximum = 0;
    for (let second = 0; second < segments.length; second++) {
      if (first === second) continue;
      const value =
        (scatters[first] + scatters[second]) /
        Math.sqrt(squaredDistance(segments[first].center, segments[second].center));
      maximum = Math.max(maximum, value);
    }
    totalDB += maximum;
  }
  return {
    silhouettes,
    silhouette: totalSilhouette / points.length,
    calinski_harabasz: between / (segments.length - 1) / (sse / (points.length - segments.length)),
    davies_bouldin: totalDB / segments.length,
  };
}
export function elbow(
  k: number,
  firstK: number,
  lastK: number,
  sse: number,
  firstSSE: number,
  lastSSE: number,
) {
  const x = (k - firstK) / (lastK - firstK);
  const y = (sse - lastSSE) / (firstSSE - lastSSE);
  return (1 - x - y) / Math.sqrt(2);
}
export const hartigan = (sse: number, nextSSE: number, n: number, k: number) =>
  (sse / nextSSE - 1) * (n - k - 1);
export function adjustedRand<X, Y>(first: X[], second: Y[]): number {
  const rows = new Map<X, number>();
  const columns = new Map<Y, number>();
  const cells = new Map<X, Map<Y, number>>();
  for (let index = 0; index < first.length; index++) {
    const left = first[index];
    const right = second[index];
    rows.set(left, (rows.get(left) ?? 0) + 1);
    columns.set(right, (columns.get(right) ?? 0) + 1);
    const row = cells.get(left) ?? new Map<Y, number>();
    row.set(right, (row.get(right) ?? 0) + 1);
    cells.set(left, row);
  }
  const pairs = (value: number) => (value * (value - 1)) / 2;
  let sx = 0;
  let sy = 0;
  let sxy = 0;
  for (const value of rows.values()) sx += pairs(value);
  for (const value of columns.values()) sy += pairs(value);
  for (const row of cells.values()) for (const value of row.values()) sxy += pairs(value);
  const z = pairs(first.length);
  const numerator = 2 * (z * sxy - sx * sy);
  const denominator = z * (sx + sy) - 2 * sx * sy;
  return denominator === 0 ? 1 : numerator / denominator;
}
